export default function Faq() {
  const [active, setActive] = useState([]);

  const toggle = (id) => {
    if (active.includes(id)) {
      setActive(active.filter((i) => i !== id));
    } else {
      setActive([id]);
    }
  };

  return (
    <div className="w-full max-w-6xl mx-auto p-6 bg-white/5 rounded-2xl shadow-2xl border border-white/10 text-stone-200 font-sans antialiased">
      {/* Section Header */}
      <div className="flex flex-col sm:flex-row justify-between items-center mb-8">
        <div>
          <div className="p-3 rounded-xl bg-amber-100/20 text-amber-400 border border-amber-500/30">
            <MoreHorizontal className="w-5 h-5" />
          </div>
          <h2 className="mt-3 text-3xl font-bold tracking-tight text-stone-100">
            Frequently Asked Questions
          </h2>
          <p className="mt-2 text-stone-400">
            Quick answers to dining essentials and specials.
          </p>
        </div>
        <div className="mt-6 sm:mt-0">
          <button
            type="button"
            className="inline-flex items-center justify-center px-4 py-2 text-sm font-medium text-stone-300 bg-white/10 border border-white/20 rounded-xl hover:bg-white/20 active:scale-95 transition-all duration-200"
          >
            Ask a Question <ChevronRight className="ml-2 w-3 h-3" />
          </button>
        </div>
      </div>

      {/* Accordion Panel */}
      <div className="space-y-4">
        {mockFAQs.map((faq) => {
          const isActive = active.includes(faq.id);
          return (
            <div key={faq.id} className="group relative border border-white/10 rounded-xl bg-white/5 p-6 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02] hover:border-white/20">
              <div className="flex justify-between items-start mb-4">
                <div className="space-y-1">
                  <h3 className="font-semibold text-stone-200 text-lg">{faq.title}</h3>
                  <p className="text-stone-400 text-sm">{faq.content}</p>
                </div>
                <button
                  type="button"
                  className="p-2 rounded-lg bg-white/5 border border-white/10 text-stone-400 transition-colors duration-200 group-hover:text-amber-400"
                  onClick={() => toggle(faq.id)}
                >
                  {isActive ? <ChevronDown className="w-4 h-4" /> : <ChevronDown className="w-4 h-4 text-amber-400" />}
                </button>
              </div>
              {isActive && (
                <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-amber-500/10 to-amber-500/0 opacity-0 group-hover:opacity-60 transition-opacity duration-300" />
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Calendar, Clock, CheckCircle2, MapPin, UtensilsCrossed, ChefHat, Wine, Phone, Sparkles, X, ArrowRight } from 'lucide-react';

const initialForm = {
  name: '',
  email: '',
  phone: '',
  date: '2024-01-14',
  time: '19:00',
  guests: 4,
  specialRequests: '',
};

const dates = [
  '2024-01-14', '2024-01-15', '2024-01-16', '2024-01-17', '2024-01-18',
  '2024-01-19', '2024-01-20', '2024-01-21', '2024-01-22', '2024-01-23',
];

export default function Reservations() {
  const [formData, setFormData] = useState(initialForm);
  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);

  const validateForm = () => {
    return formData.name.trim() && formData.email.includes('@') && formData.phone.length === 10;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!validateForm()) {
      alert('Please fill out the required fields correctly.');
      return;
    }

    setIsLoading(true);
    setTimeout(() => {
      setIsLoading(false);
      setIsSuccess(true);
    }, 1200);
  };

  const TimeSlot = ({ time, isOccupied = false }) => {
    return (
      <div className="group relative flex items-center gap-2 rounded-xl bg-amber-900/10 px-4 py-3 text-stone-400 transition-all duration-300 hover:bg-amber-900/20">
        {isOccupied ? (
          <div className="absolute -inset-0.5 bg-amber-500/10" />
        ) : (
          <div className="absolute -inset-0.5 bg-amber-500/10" />
        )}
        <div className="relative flex items-center gap-2">
          <Clock className="w-4 h-4 text-stone-500" />
          <span className="text-xs font-medium text-stone-300">{time}</span>
        </div>
        {isOccupied ? (
          <span className="inline-flex items-center gap-1 text-sm text-amber-300 opacity-80">
            <Sparkles className="w-3.5 h-3.5 text-amber-400" /> Full Table
          </span>
        ) : (
          <span className="inline-flex items-center gap-1 text-sm text-amber-300 opacity-80">
            <Sparkles className="w-3.5 h-3.5 text-amber-400" /> Available
          </span>
        )}
      </div>
    );
  };

  return (
    <div className="w-full max-w-7xl mx-auto py-24 sm:py-32">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6">
        <div>
          <h2 className="text-xl font-bold tracking-tight text-stone-100 sm:text-2xl">Book Your Table</h2>
          <p className="text-sm text-stone-400">Join us for an unforgettable dining experience at Casa Verde.</p>
        </div>
        <div className="flex flex-col sm:flex-row sm:gap-3">
          <button className="inline-flex items-center gap-2 self-start rounded-xl bg-white/5 px-4 py-2 text-sm font-medium text-stone-300 transition-colors hover:bg-white/10 active:text-stone-500">
            <MapPin className="w-4 h-4" /> <span>Map & Directions</span>
          </button>
          <button className="inline-flex items-center gap-2 self-start rounded-xl bg-white/5 px-4 py-2 text-sm font-medium text-stone-300 transition-colors hover:bg-white/10 active:text-stone-500">
            <Phone className="w-4 h-4" /> <span>Contact Us</span>
          </button>
        </div>
      </div>

      <div className="mt-12 sm:mt-16">
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
          {dates.map((date) => (
            <div key={date} className="group relative overflow-hidden rounded-2xl bg-white/5 p-6 transition-all duration-300 hover:bg-white/10 hover:scale-[1.01]">
              <div className="absolute -top-12 -right-12 w-32 bg-amber-500/20 backdrop-blur-xl transition-transform duration-500 group-hover:-translate-x-2 group-hover:-translate-y-2" />
              <h3 className="text-xl font-bold text-stone-100 group-hover:text-amber-400">{date}</h3>
              <div className="grid grid-cols-2 gap-4">
                {[18, 19, 20, 21, 22].map((hour) => (
                  <TimeSlot key={hour} time={`${hour}:00`} />
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>

      <div className="mt-16 sm:mt-20">
        <div className="relative bg-white/5 p-8 shadow-2xl transition-all duration-300 hover:shadow-3xl">
          <div className="absolute -inset-1 bg-white/10" />
          <div className="relative rounded-2xl bg-white/10 p-6 backdrop-blur-xl border border-white/10">
            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div className="relative">
                  <label htmlFor="name" className="sr-only">Full Name</label>
                  <input
                    type="text"
                    id="name"
                    value={formData.name}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="Full Name"
                    className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-stone-400 border border-white/10 placeholder:text-stone-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                    required
                  />
                </div>
                <div className="relative">
                  <label htmlFor="email" className="sr-only">Email Address</label>
                  <input
                    type="email"
                    id="email"
                    value={formData.email}
                    onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                    placeholder="example@domain.com"
                    className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-stone-400 border border-white/10 placeholder:text-stone-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                    required
                  />
                </div>
              </div>
              <div className="relative">
                <label htmlFor="phone" className="sr-only">Phone Number</label>
                <input
                  type="tel"
                  id="phone"
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  placeholder="+1 (123) 456-7890"
                  className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-stone-400 border border-white/10 placeholder:text-stone-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                  required
                />
              </div>
              <div className="relative">
                <label htmlFor="date" className="sr-only">Date</label>
                <input
                  type="date"
                  id="date"
                  value={formData.date}
                  onChange={(e) => setFormData({ ...formData, date: e.target.value })}
                  min="2024-01-14"
                  className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-stone-400 border border-white/10 placeholder:text-stone-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                  required
                />
              </div>
              <div className="relative">
                <label htmlFor="time" className="sr-only">Time</label>
                <input
                  type="time"
                  id="time"
                  value={formData.time}
                  onChange={(e) => setFormData({ ...formData, time: e.target.value })}
                  min="18:00"
                  max="22:00"
                  className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-stone-400 border border-white/10 placeholder:text-stone-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                  required
                />
              </div>
              <div className="relative">
                <label htmlFor="guests" className="sr-only">Guests</label>
                <input
                  type="number"
                  id="guests"
                  value={formData.guests}
                  onChange={(e) => setFormData({ ...formData, guests: e.target.value })}
                  min="1"
                  max="12"
                  className="w-full rounded-xl bg-white/5 py-3 pl-4 pr-10 text-stone-400 border border-white/10 placeholder:text-stone-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                  required
                />
              </div>
              <div>
                <label htmlFor="specialRequests" className="sr-only">Special Requests</label>
                <textarea
                  id="specialRequests"
                  value={formData.specialRequests}
                  onChange={(e) => setFormData({ ...formData, specialRequests: e.target.value })}
                  placeholder="Any dietary restrictions or seating preferences?"
                  rows="4"
                  className="w-full rounded-xl bg-white/5 py-3 px-4 text-stone-400 border border-white/10 placeholder:text-stone-600 focus:ring-2 focus:ring-amber-500/30 outline-none transition-all"
                />
              </div>
              <button
                type="submit"
                disabled={!validateForm() || isLoading}
                className="w-full rounded-xl bg-amber-800 py-4 text-center font-semibold text-stone-100 shadow-lg transition-all hover:shadow-2xl active:scale-95 disabled:opacity-50"
              >
                {isLoading ? 'Reserving...' : 'Reserve Table'}
              </button>
            </form>
          </div>
        </div>
      </div>

      {isSuccess && (
        <div className="mt-12 sm:mt-16">
          <div className="relative bg-white/5 p-8 shadow-2xl transition-all duration-300 hover:shadow-3xl">
            <div className="absolute -inset-1 bg-white/10" />
            <div className="relative rounded-2xl bg-white/10 p-6 backdrop-blur-xl border border-white/10 flex flex-col items-center gap-4">
              <CheckCircle2 className="w-12 h-12 text-emerald-400" />
              <h3 className="text-xl font-bold text-stone-100">Reservation Confirmed!</h3>
              <p className="text-sm text-stone-400">We've saved your seat. See you at the table!</p>
              <button
                onClick={() => setIsSuccess(false)}
                className="inline-flex items-center gap-2 self-start rounded-xl bg-white/5 px-4 py-2 text-sm font-medium text-stone-300 transition-colors hover:bg-white/10 active:text-stone-500"
              >
                <ArrowRight className="w-4 h-4" /> Continue Dining
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

.font-display { font-family: 'Playfair Display', Georgia, serif; }
.font-body { font-family: 'Inter', system-ui, sans-serif; }
body { font-family: 'Inter', system-ui, sans-serif; }

@keyframes reveal-up { from { opacity: 0; transform: translateY(28px); } to { opacity: 1; transform: translateY(0); } }
.reveal { opacity: 0; }
.reveal-visible { animation: reveal-up 0.8s cubic-bezier(0.22, 1, 0.36, 1) both; }
@media (prefers-reduced-motion: reduce) {
  .reveal { opacity: 1; }
  .reveal-visible { animation: none; }
}
@keyframes fade-up { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: translateY(0); } }
.animate-fade-up { animation: fade-up 0.7s ease-out both; }
@keyframes float-slow { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }
.animate-float-slow { animation: float-slow 5s ease-in-out infinite; }
@keyframes marquee { from { transform: translateX(0); } to { transform: translateX(-50%); } }
.animate-marquee { animation: marquee 30s linear infinite; }

